var picker = new ArcDateRangePicker
{
    Label = "Report period",
    Width = 320,
    Range = new ArcDateRange(DateTime.Today.AddDays(-13), DateTime.Today),
    Presets = ArcDateRangePreset.Defaults,
    Months = ArcRangeMonths.Two
};

picker.RangeChanged += (_, range) =>
    statusText.Text = $"{range.Start:yyyy-MM-dd} - {range.End:yyyy-MM-dd} ({range.Days} days)";
